// Revenue conversion hook: records paid events on checkout success
// Called by checkout success endpoint after payment confirmation

const fs = require('fs');
const path = require('path');

const REVENUE_LOG = path.join(__dirname, '..', 'data', 'revenue_events.jsonl');

function recordPaidEvent(orderId, amount, currency = 'USD') {
  const event = {
    type: 'paid',
    orderId,
    amount,
    currency,
    timestamp: new Date().toISOString()
  };
  fs.appendFileSync(REVENUE_LOG, JSON.stringify(event) + '\n');
  return event;
}

// Export for use in checkout route
module.exports = { recordPaidEvent };
